import{_ as e,o as r,c as a,a2 as d}from"./chunks/framework.CYjxsSA2.js";const _=JSON.parse('{"title":"MCP 外部工具服务器","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/mcp.md","filePath":"advanced/mcp.md"}'),o={name:"advanced/mcp.md"};function n(l,t,i,s,c,h){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="mcp-外部工具服务器" tabindex="-1">MCP 外部工具服务器 <a class="header-anchor" href="#mcp-外部工具服务器" aria-label="Permalink to &quot;MCP 外部工具服务器&quot;">​</a></h1><p>MCP（Model Context Protocol）用于把<strong>外部工具服务器</strong>挂进<a href="/vaelor/guide/army.html">军团</a>的工具表，让军团调用你自己的工具。</p><h2 id="配置入口" tabindex="-1">配置入口 <a class="header-anchor" href="#配置入口" aria-label="Permalink to &quot;配置入口&quot;">​</a></h2><p><strong>系统配置 → MCP</strong>，可添加多个 Server，逐个启用 / 禁用。支持两种连接方式：</p><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><strong>本地进程</strong></td><td>在本机启动一个工具服务进程来提供工具</td></tr><tr><td><strong>网络端点</strong></td><td>连接远端服务的地址</td></tr></tbody></table><p>保存并启用后，该 Server 的工具会出现在军团的工具列表中，可按角色裁剪。</p><h2 id="典型用法" tabindex="-1">典型用法 <a class="header-anchor" href="#典型用法" aria-label="Permalink to &quot;典型用法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>做法</th></tr></thead><tbody><tr><td>接入内部资产查询</td><td>暴露一个 <code>query_asset</code>，军团的侦察阶段可直接查内网 CMDB</td></tr><tr><td>接入自研 PoC 平台</td><td>暴露 <code>run_poc</code>，把沉淀的验证脚本变成军团可调用的工具</td></tr><tr><td>接入工单系统</td><td>暴露 <code>create_ticket</code>，验证完漏洞直接开单</td></tr></tbody></table><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>MCP 工具同样受<strong>权限档位</strong>与<strong>计划模式</strong>约束</li><li>Server 未启用或连不上时，该 Server 的<strong>整批工具会一并消失</strong>，不是逐个报错</li><li>工具消失时先看两处：Server 开关是否打开、本地进程是否还在（或远端地址是否可达）</li><li>MCP 返回内容会进入会话上下文，返回体过大时请精简</li><li>挂载外部工具等于授予军团调用能力，只接入你信任的 Server</li></ul>',10)])])}const m=e(o,[["render",n]]);export{_ as __pageData,m as default};
